import { useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { useProjectsContext } from './projects-context.js';
import { toggleTask } from './task-tree.js';
import { flattenLeaves, projectAreas } from './task-views.js';
import { ProjectHeader } from './project-tabs.js';
import { ProgressBar } from './progress-bar.js';
import { CheckRow } from './check-row.js';
import { NotFound } from './project-overview-page.js';
import styles from './ui.module.css';

type Filter = 'remaining' | 'all' | 'done';

/**
 * Checklist frame: every checkable task in the project as one flat list,
 * grouped by area, with a Remaining / All / Done filter.
 */
export function ChecklistPage() {
  const { projectId } = useParams();
  const { projects, loading, updateTasks } = useProjectsContext();
  const [filter, setFilter] = useState<Filter>('remaining');
  const project = projects.find((p) => p.id === projectId);

  if (loading) return <p className={styles.empty}>Loading…</p>;
  if (!project) return <NotFound />;

  const keep = (done: boolean) => (filter === 'all' ? true : filter === 'done' ? done : !done);

  const groups = projectAreas(project).map((a) => {
    const items = a.task.subtasks?.length ? flattenLeaves(a.task.subtasks) : [{ task: a.task, path: [], pathIds: [] }];
    return { area: a, items: items.filter((i) => keep(i.task.done)) };
  });
  const shown = groups.reduce((n, g) => n + g.items.length, 0);

  return (
    <div className={styles.page}>
      <ProjectHeader project={project} />

      <div className={styles.segmented} role="radiogroup" aria-label="Filter tasks">
        {(['remaining', 'all', 'done'] as Filter[]).map((f) => (
          <button key={f} role="radio" aria-checked={filter === f} className={`${styles.segment} ${filter === f ? styles.segmentActive : ''}`} onClick={() => setFilter(f)}>
            {f[0].toUpperCase() + f.slice(1)}
          </button>
        ))}
      </div>

      {shown === 0 ? (
        <div className={styles.card}>
          <p className={styles.empty}>{filter === 'remaining' ? '🎉 Nothing left — everything is done.' : 'No tasks here yet.'}</p>
        </div>
      ) : (
        groups.filter((g) => g.items.length).map(({ area, items }) => (
          <section key={area.task.id} className={styles.card}>
            <div className={styles.groupHead}>
              <Link to={`/projects/${project.id}/areas/${area.task.id}`} className={styles.groupTitle}>{area.task.title} ›</Link>
              <span className={styles.groupPct}>{area.done}/{area.total} · {area.percent}%</span>
            </div>
            <ProgressBar percent={area.percent} color={project.color} />
            <ul className={styles.checkList}>
              {items.map((i) => (
                <CheckRow
                  key={i.task.id}
                  task={i.task}
                  path={i.path}
                  color={project.color}
                  onToggle={() => updateTasks(project.id, (t) => toggleTask(t, i.task.id))}
                />
              ))}
            </ul>
          </section>
        ))
      )}
    </div>
  );
}
